// shipped as offline geometry; only the icons below are bundled. Colours live in Styles/FileIcons.axaml (FileIcon.<Id>).
public sealed class FileIcon
{
    public const double Size = 16;
    public string Id { get; }
    public string BrushKey => "FileIcon." + Id;
    // One shared, frozen geometry per icon: every row, tab and result reuses the same instance.
    public Geometry Geometry => _geometry ??= Build();
    private readonly string _data; private readonly double _x, _y, _box;
    private Geometry? _geometry;
    internal FileIcon(string id, string data, double x, double y, double box) { Id = id; _data = data; _x = x; _y = y; _box = box; }
    private Geometry Build()
    {
        var geometry = Geometry.Parse(_data);
        // Map the SVG viewBox onto the 16px icon box.
        var scale = Size / _box;
        geometry.Transform = new MatrixTransform(Matrix.CreateTranslation(-_x, -_y) * Matrix.CreateScale(scale, scale));
        return geometry;
    }
    public override string ToString() => Id;
}

