    // Large folders repeat the same names and extensions; cache the name/extension result per file name.
    private static readonly ConcurrentDictionary<string, FileIcon?> Cache = new(StringComparer.OrdinalIgnoreCase);
    public static int CacheCount => Cache.Count;

    public static FileIcon For(string? path, bool isBinary = false)
    {
        var name = System.IO.Path.GetFileName(path ?? "");
        var match = Cache.GetOrAdd(name, static n => Names.TryGetValue(n, out var byName) ? byName
            : Extensions.TryGetValue(System.IO.Path.GetExtension(n), out var byExtension) ? byExtension : null);
        return match ?? (isBinary ? Binary : File);
    }
